steps.solution:
def parse_mark(text, top=100):
    """Whole number 0 to top, or None."""
    t = text.strip()
    if not t.isdigit() or int(t) > top:
        return None
    return int(t)

m = parse_mark(input("Mark: "))
if m is None:
    print("Type 0 to 100, in digits")
else:
    print("Mark:", m)

