steps.solution:
def bill_amount(units):
    if units <= 100:
        return units * 0.50
    if units <= 300:
        return 50 + (units - 100) * 0.75
    return 200 + (units - 300) * 1.10

def format_bill(u, a):
    return f"Used {u} units, due {a:.2f}"

u = int(input("Units: "))
print(format_bill(u, bill_amount(u)))

